```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_route53_zone" "primary_zone" {
  name = "primary.example.com"
}

resource "aws_elb" "main_elb" {
  name               = "main-elb"
  availability_zones = ["us-west-2a", "us-west-2b", "us-west-2c"]

  listener {
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    target              = "HTTP:80/"
    interval            = 30
    timeout             = 5
  }
}

resource "aws_route53_record" "elb_alias_record" {
  name    = "main"
  type    = "A"
  zone_id = aws_route53_zone.primary_zone.zone_id

  alias {
    name                   = aws_elb.main_elb.dns_name
    zone_id                = aws_elb.main_elb.zone_id
    evaluate_target_health = true
  }
}
```

This Terraform configuration sets up a Route 53 zone named "primary.example.com" and an Elastic Load Balancer named "main-elb". It also creates a Route 53 record that aliases the ELB. The ELB is configured with a listener and a health check. All resources are interdependent as required by the prompt.

