resource "aws_db_instance" "primary_db" {
  instance_class = "db.t3.micro"
}

resource "aws_db_instance" "replica_1_db" {
  instance_class = "db.t3.micro"
}

resource "aws_db_instance" "replica_2_db" {
  instance_class = "db.t3.micro"
}

resource "aws_route53_record" "primary_record" {
  name       = "primary"
  type       = "CNAME"
  zone_id    = aws_route53_zone.main_zone.zone_id
  ttl        = 300
  records    = [aws_db_instance.primary_db.endpoint]
  set_identifier = "primary"

  weighted_routing_policy {
    weight = 150
  }
}

resource "aws_route53_record" "replica_1_record" {
  name       = "replica-1"
  type       = "CNAME"
  zone_id    = aws_route53_zone.main_zone.zone_id
  ttl        = 300
  records    = [aws_db_instance.replica_1_db.endpoint]
  set_identifier = "replica-1"

  weighted_routing_policy {
    weight = 450
  }
}

resource "aws_route53_record" "replica_2_record" {
  name       = "replica-2"
  type       = "CNAME"
  zone_id    = aws_route53_zone.main_zone.zone_id
  ttl        = 300
  records    = [aws_db_instance.replica_2_db.endpoint]
  set_identifier = "replica-2"

  weighted_routing_policy {
    weight = 400
  }
}
```

This Terraform configuration sets up a Route 53 zone named "main" and three RDS database instances: a primary and two replicas. It configures weighted routing policies in Route 53 to distribute traffic between the primary and replica instances based on specified weights.

