### Description
This Terraform program creates a basic AWS CodeBuild project with an example IAM role and a GitHub source. The IAM role is configured with the necessary permissions for CodeBuild, and the CodeBuild project is set up to use a GitHub repository as its source.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "codebuild-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents",
            "s3:GetObject",
            "s3:PutObject"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_codebuild_project" "basic_codebuild_project" {
  name         = "basic-codebuild-project"
  service_role = aws_iam_role.codebuild_service_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    git_clone_depth = 1
    report_build_status = true
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
- **IAM Role**: An IAM role named `codebuild-service-role` is created with an assume role policy that allows CodeBuild to assume the role. An inline policy grants necessary permissions for logging and S3 access.
- **CodeBuild Project**: A CodeBuild project named `basic-codebuild-project` is created. It uses the previously defined IAM role as its service role. The source is configured to pull from a GitHub repository, and the environment is set up with a small Linux container. No artifacts are produced by this project.

