### Description
This Terraform program creates an AWS Lex bot with multiple slots. It includes the following resources:
1. **aws_lex_slot_type**: Defines two slot types (`slot_type_1` and `slot_type_2`).
2. **aws_lex_intent**: Defines an intent (`intent_with_slots`) that uses the previously defined slot types.
3. **aws_lex_bot**: Creates a Lex bot that uses the defined intent.
4. **aws_lex_alias**: Creates an alias for the Lex bot.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lex_slot_type" "slot_type_1" {
  name = "SlotType1"

  enumeration_value {
    value = "Value1"
  }

  enumeration_value {
    value = "Value2"
  }
}

resource "aws_lex_slot_type" "slot_type_2" {
  name = "SlotType2"

  enumeration_value {
    value = "ValueA"
  }

  enumeration_value {
    value = "ValueB"
  }
}

resource "aws_lex_intent" "intent_with_slots" {
  name = "IntentWithSlots"

  slot {
    name               = "Slot1"
    slot_constraint    = "Required"
    slot_type          = aws_lex_slot_type.slot_type_1.name
    slot_type_version  = "$LATEST"
  }

  slot {
    name               = "Slot2"
    slot_constraint    = "Required"
    slot_type          = aws_lex_slot_type.slot_type_2.name
    slot_type_version  = "$LATEST"
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_bot" "lex_bot" {
  name           = "MyLexBot"
  child_directed = false

  intent {
    intent_name    = aws_lex_intent.intent_with_slots.name
    intent_version = "$LATEST"
  }
}

resource "aws_lex_alias" "lex_bot_alias" {
  bot_name       = aws_lex_bot.lex_bot.name
  bot_version    = "$LATEST"
  name           = "MyLexBotAlias"
  description    = "Alias for MyLexBot"
}
```

