### Description
This Terraform program creates a Kinesis Firehose Delivery Stream with an extended S3 Destination, enabling dynamic partitioning. The program includes the necessary resources: an S3 bucket for the Firehose destination and the Firehose delivery stream itself. The S3 bucket is configured with the appropriate permissions to allow the Firehose delivery stream to write data.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "firehose_destination_bucket" {
  bucket = "firehose-destination-bucket-${random_string.suffix.result}"
  acl    = "private"

  # Ensure the bucket has the necessary permissions for the Kinesis Firehose delivery stream to write data.
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "s3:AbortMultipartUpload"
        Resource = "${aws_s3_bucket.firehose_destination_bucket.arn}/*"
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.firehose_destination_bucket.arn
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "s3:PutObject"
        Resource = "${aws_s3_bucket.firehose_destination_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = "firehose-delivery-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn       = aws_iam_role.firehose_role.arn
    bucket_arn     = aws_s3_bucket.firehose_destination_bucket.arn
    prefix         = "data/"
    buffering_interval = 300
    buffering_size   = 5
    compression_format = "GZIP"
    dynamic_partitioning_configuration {
      enabled = true
    }
  }
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_policy" {
  name = "firehose-policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:ListBucket",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.firehose_destination_bucket.arn,
          "${aws_s3_bucket.firehose_destination_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

This Terraform configuration sets up an S3 bucket and a Kinesis Firehose Delivery Stream with an extended S3 destination, enabling dynamic partitioning. The IAM role and policy ensure that the Firehose delivery stream has the necessary permissions to write to the S3 bucket.

