### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "app_name" {
  description = "Name of the Kinesis Analytics application"
  default     = "MyKinesisAnalyticsApp"
}

variable "log_group_name" {
  description = "Name of the CloudWatch Log Group"
  default     = "/aws/kinesis-analytics/my-app"
}

variable "log_stream_name" {
  description = "Name of the CloudWatch Log Stream"
  default     = "my-app-log-stream"
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "${var.app_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_analytics_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/KinesisAnalyticsReadOnlyAccess"
  role       = aws_iam_role.kinesis_analytics_role.name
}

