### Description

This Terraform program creates an ElastiCache user with an associated IAM role and policy. The IAM role is configured to allow ElastiCache operations, and the ElastiCache user is created with the necessary permissions.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "elasticsearch_user_role" {
  name = "elasticsearch-user-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "elasticsearch_user_policy" {
  name = "elasticsearch-user-policy"
  role = aws_iam_role.elasticsearch_user_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticache:Describe*",
          "elasticache:List*",
          "elasticache:CreateUser",
          "elasticache:UpdateUser",
          "elasticache:DeleteUser"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_elasticache_user" "elasticsearch_user" {
  user_id     = "my-elasticsearch-user"
  user_name   = "my-elasticsearch-user"
  access_string = "on ~app::* -@allusers"
  engine      = "redis"

  depends_on = [
    aws_iam_role.elasticsearch_user_role,
    aws_iam_role_policy.elasticsearch_user_policy
  ]
}
```

This configuration sets up an IAM role with a policy that allows ElastiCache operations, and then creates an ElastiCache user with the specified access string and engine type. The ElastiCache user depends on the IAM role and policy being created first.

