### Description
This Terraform program sets up a primary Redshift cluster in `us-east-1` and a replica Redshift cluster in `us-east-2`. The replica cluster is configured to replicate data from the primary cluster. The program includes the necessary IAM roles and policies to allow the primary cluster to replicate data to the replica cluster.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Redshift to access S3
resource "aws_iam_role" "redshift_s3_access_role" {
  name = "redshift-s3-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Redshift to access S3
resource "aws_iam_policy" "redshift_s3_access_policy" {
  name        = "redshift-s3-access-policy"
  description = "Allows Redshift to access S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::*",
          "arn:aws:s3:::*/"
        ]
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "redshift_s3_access_policy_attachment" {
  policy_arn = aws_iam_policy.redshift_s3_access_policy.arn
  role       = aws_iam_role.redshift_s3_access_role.name
}

# Primary Redshift Cluster in us-east-1
resource "aws_redshift_cluster" "redshift_cluster_us_east_1" {
  cluster_identifier = "primary-redshift-cluster"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  iam_roles          = [aws_iam_role.redshift_s3_access_role.arn]

  snapshot_copy {
    destination_region = "us-east-2"
  }
}

# Replica Redshift Cluster in us-east-2
resource "aws_redshift_cluster" "redshift_cluster_us_east_2" {
  provider = aws.us_east_2

  cluster_identifier = "replica-redshift-cluster"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  iam_roles          = [aws_iam_role.redshift_s3_access_role.arn]
  cluster_type       = "replication-target"
  replication_source_identifier = aws_redshift_cluster.redshift_cluster_us_east_1.cluster_identifier
}

provider "aws" {
  alias  = "us_east_2"
  region = "us-east-2"
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured for `us-east-1` and aliased for `us-east-2`.
2. **IAM Role and Policy**: An IAM role and policy are created to allow the Redshift clusters to access S3.
3. **Primary Redshift Cluster**: A Redshift cluster is created in `us-east-1` with the necessary configurations, including a snapshot copy configuration to replicate data to `us-east-2`.
4. **Replica Redshift Cluster**: A Redshift cluster is created in `us-east-2` as a replication target, referencing the primary cluster for data replication.

