### Description
This Terraform program creates an AWS Lambda function and sets up a scheduled event to invoke it every 15 minutes using Amazon EventBridge (CloudWatch Events). The Lambda function is granted the necessary permissions through an IAM role.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "lambda_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_lambda_function" "my_lambda_function" {
  function_name = "my_lambda_function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function.zip"

  source_code_hash = filebase64sha256("lambda_function.zip")
}

resource "aws_cloudwatch_event_rule" "lambda_schedule" {
  name                = "lambda_schedule"
  schedule_expression = "rate(15 minutes)"
}

resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.lambda_schedule.name
  target_id = "lambda_target"
  arn       = aws_lambda_function.my_lambda_function.arn

  input = jsonencode({
    key = "value"
  })
}

resource "aws_lambda_permission" "allow_cloudwatch_event" {
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.my_lambda_function.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.lambda_schedule.arn
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **IAM Role**: An IAM role (`lambda_execution_role`) is created with a trust policy allowing Lambda to assume the role. An inline policy grants permissions for logging.
3. **Lambda Function**: A Lambda function (`my_lambda_function`) is defined with a handler, runtime, and a zip file containing the function code. The `source_code_hash` ensures the function is updated when the code changes.
4. **EventBridge Rule**: An EventBridge rule (`lambda_schedule`) is set up to trigger every 15 minutes.
5. **EventBridge Target**: The EventBridge target (`lambda_target`) specifies the Lambda function to invoke when the rule is triggered.
6. **Lambda Permission**: A permission (`allow_cloudwatch_event`) is added to allow EventBridge to invoke the Lambda function.

