### Description
This Terraform program creates an AWS SageMaker image along with an IAM role that grants the necessary permissions for the SageMaker image. The IAM role includes an inline policy that allows SageMaker operations.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "sagemaker_role" {
  name = "sagemaker-image-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "sagemaker-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "sagemaker:*",
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage",
            "ecr:BatchCheckLayerAvailability"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_sagemaker_image" "sagemaker_image" {
  image_name = "my-sagemaker-image"
  role_arn   = aws_iam_role.sagemaker_role.arn

  description = "My SageMaker Image"
  display_name = "My SageMaker Image"
}
```

This configuration sets up an IAM role with the necessary permissions for SageMaker operations and then creates a SageMaker image using that role. The IAM role includes an inline policy that allows SageMaker-related actions and ECR operations.

