### Description
The Terraform program below creates an EC2 instance using the latest Amazon Linux 2 AMI with specific CPU options: `cpu_count=2` and `cores_per_threads_per_core=2`. The program includes the necessary provider configuration and specifies the required attributes for the `aws_instance` resource.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners     = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_instance" "example_instance" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.medium"

  cpu_options {
    core_count          = 2
    threads_per_core    = 2
  }

  tags = {
    Name = "ExampleInstance"
  }
}
```

