### Description
This Terraform program creates a VPC with a public and private subnet. It then defines an EC2 Fleet that includes 5 On-Demand and 4 Spot Instances using a launch template. The launch template specifies the use of the latest Amazon Linux 2 AMI.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "my_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.my_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
}

resource "aws_subnet" "private_subnet" {
  vpc_id                  = aws_vpc.my_vpc.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = false
  availability_zone       = "us-west-2b"
}

resource "aws_ami" "latest_amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]
  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_launch_template" "my_launch_template" {
  name          = "my-launch-template"
  image_id      = aws_ami.latest_amazon_linux_2.id
  instance_type = "t3.micro"
}

resource "aws_ec2_fleet" "my_ec2_fleet" {
  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.my_launch_template.id
      version            = "$Latest"
    }
  }

  target_capacity_specification {
    default_target_capacity_type = "spot"
    total_target_capacity        = 9
    spot_target_capacity         = 4
    on_demand_target_capacity    = 5
  }

  on_demand_options {
    allocation_strategy = "lowest-price"
  }

  spot_options {
    allocation_strategy = "lowest-price"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **VPC Creation**: A VPC is created with a CIDR block of `10.0.0.0/16`.
3. **Subnet Creation**: Two subnets are created within the VPC:
   - `public_subnet`: A public subnet with a CIDR block of `10.0.1.0/24` in the `us-west-2a` availability zone, with public IP mapping enabled.
   - `private_subnet`: A private subnet with a CIDR block of `10.0.2.0/24` in the `us-west-2b` availability zone, with public IP mapping disabled.
4. **AMI Selection**: The latest Amazon Linux 2 AMI is selected using a filter.
5. **Launch Template**: A launch template is created using the selected AMI and specifying the instance type as `t3.micro`.
6. **EC2 Fleet**: An EC2 Fleet is defined with:
   - 5 On-Demand instances and 4 Spot instances.
   - The launch template is specified for the fleet.
   - Target capacity specifications are set for both On-Demand and Spot instances.
   - Allocation strategies are set to `lowest-price` for both On-Demand and Spot instances.

