### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster in the `us-east-1` region with logging enabled to a CloudWatch log group. The program also sets up an IAM role and policy required for the MSK cluster to operate and log to CloudWatch.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_cloudwatch_log_group" "msk_cluster_logs" {
  name              = "msk-cluster-logs"
  retention_in_days = 30
}

resource "aws_iam_policy" "msk_cluster_policy" {
  name        = "msk-cluster-policy"
  description = "Policy for MSK cluster operations and logging to CloudWatch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "msk_cluster_role" {
  name               = "msk-cluster-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  policy_arn = aws_iam_policy.msk_cluster_policy.arn
  role       = aws_iam_role.msk_cluster_role.name
}

resource "aws_msk_cluster" "msk_cluster_with_logging" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"]
    instance_type  = "t3.medium"
    security_groups = ["sg-12345678"]
  }

  logging_info {
    cloudwatch_logs {
      enabled   = true
      log_group = aws_cloudwatch_log_group.msk_cluster_logs.name
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.attach_msk_policy_to_role
  ]
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **CloudWatch Log Group**: A CloudWatch log group named `msk-cluster-logs` is created with a retention period of 30 days.
3. **IAM Policy**: An IAM policy named `msk-cluster-policy` is created to allow the necessary actions for logging to CloudWatch.
4. **IAM Role**: An IAM role named `msk-cluster-role` is created with an assume role policy that allows EC2 to assume the role.
5. **IAM Role Policy Attachment**: The IAM policy is attached to the IAM role.
6. **MSK Cluster**: An MSK cluster named `my-msk-cluster` is created with three broker nodes, using the specified instance type and subnets. Logging to the CloudWatch log group is enabled.

This configuration ensures that the MSK cluster is properly set up with logging to CloudWatch and the necessary IAM permissions.

