### Description
The Terraform program below creates a managed Amazon MSK (Managed Streaming for Kafka) cluster in the `us-east-1` region. The cluster is configured to log to a Kinesis Firehose delivery stream. The program includes the necessary resources such as the MSK cluster, VPC, subnets, security groups, and IAM roles required for the setup.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a VPC
resource "aws_vpc" "example" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Create subnets
resource "aws_subnet" "example" {
  count             = 3
  vpc_id            = aws_vpc.example.id
  cidr_block        = cidrsubnet(aws_vpc.example.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

# Create an Internet Gateway
resource "aws_internet_gateway" "example" {
  vpc_id = aws_vpc.example.id
}

# Create a Route Table
resource "aws_route_table" "example" {
  vpc_id = aws_vpc.example.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.example.id
  }
}

# Associate Subnets with Route Table
resource "aws_route_table_association" "example" {
  count          = length(aws_subnet.example)
  subnet_id      = element(aws_subnet.example[*].id, count.index)
  route_table_id = aws_route_table.example.id
}

# Create Security Group
resource "aws_security_group" "example" {
  name        = "msk-sg"
  description = "Allow Kafka traffic"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create IAM Role for MSK
resource "aws_iam_role" "msk_role" {
  name = "msk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Attach Policy to IAM Role
resource "aws_iam_role_policy_attachment" "msk_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
  role       = aws_iam_role.msk_role.name
}

# Create MSK Cluster
resource "aws_msk_cluster" "example" {
  cluster_name           = "example-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets  = aws_subnet.example[*].id
    instance_type   = "t3.medium"
    security_groups = [aws_security_group.example.id]
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/example"
      }
      firehose {
        enabled         = true
        delivery_stream = "example-firehose"
      }
      s3 {
        enabled = false
      }
    }
  }

  tags = {
    Name = "example-msk-cluster"
  }
}
```

This Terraform configuration sets up a basic MSK cluster with logging to Kinesis Firehose. It includes a VPC, subnets, security groups, and an IAM role necessary for the MSK cluster to function. Adjust the configuration as needed for your specific requirements.

