### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with encryption at rest. The program includes the following resources:
1. An S3 bucket to store MSK logs.
2. Server-side encryption configuration for the S3 bucket.
3. An MSK cluster configured to use the encrypted S3 bucket for logging.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket-${random_string.suffix.result}"
  acl    = "private"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_logs_bucket_encryption" {
  bucket = aws_s3_bucket.msk_logs_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"]
    instance_type  = "t3.medium"
    security_groups = ["sg-12345678"]
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = false
      }
      firehose {
        enabled   = false
      }
      s3 {
        enabled         = true
        bucket        = aws_s3_bucket.msk_logs_bucket.bucket
        prefix        = "msk-logs/"
      }
    }
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **S3 Bucket**: An S3 bucket named `msk-logs-bucket-<random_suffix>` is created to store MSK logs.
3. **Server-Side Encryption Configuration**: The S3 bucket is configured with server-side encryption using the AES256 algorithm.
4. **MSK Cluster**: A managed MSK cluster is created with the specified Kafka version and number of broker nodes. The cluster is configured to log to the previously created S3 bucket.
5. **Random String**: A random string is generated to ensure the S3 bucket name is unique.

