### Description
This Terraform program creates a serverless Amazon Managed Streaming for Kafka (MSK) cluster with 3 broker nodes. It includes the necessary IAM role and policy attachments to ensure the MSK cluster has the required permissions.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for MSK Serverless
resource "aws_iam_role" "msk_serverless_role" {
  name = "msk-serverless-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "msk.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for MSK Serverless
resource "aws_iam_policy" "msk_serverless_policy" {
  name        = "msk-serverless-policy"
  description = "Policy for MSK Serverless operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:DescribeCluster",
          "kafka:GetBootstrapBrokers",
          "kafka:ListClusters",
          "kafka:ListConfigurationRevisions",
          "kafka:ListConfigurations",
          "kafka:ListTagsForResource",
          "kafka:TagResource",
          "kafka:UntagResource"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the IAM Policy to the IAM Role
resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  role       = aws_iam_role.msk_serverless_role.name
  policy_arn = aws_iam_policy.msk_serverless_policy.arn
}

# MSK Serverless Cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-serverless-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"]  # Replace with your subnet IDs
    instance_type  = "m5.large"
    security_groups = ["sg-12345678"]  # Replace with your security group ID
  }

  storage_mode = "serverless"
}
```

### Notes
- Ensure that the subnet IDs and security group IDs provided in the `broker_node_group_info` block are valid and exist in your AWS account.
- The `kafka_version` should be compatible with the serverless mode.
- The IAM policy attached to the role should have the necessary permissions for the MSK serverless operations. Adjust the policy as needed based on your specific requirements.

