provider "aws" {
  region = "us-east-1"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "debezium-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1", "subnet-0123456789abcdef2"]
    instance_type  = "t3.medium"
    security_groups = ["sg-0123456789abcdef0"]
  }

  client_authentication {
    unauthenticated = true
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-east-1:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/debezium-msk-cluster"
      }
    }
  }
}

resource "aws_mskconnect_custom_plugin" "mskconnect_custom_plugin" {
  name         = "debezium-custom-plugin"
  content_type = "ZIP"

  location {
    s3 {
      bucket_arn = "arn:aws:s3:::debezium-bucket"
      file_key   = "debezium.zip"
    }
  }
}

resource "aws_iam_role" "mskconnect_service_execution_role" {
  name = "mskconnect-service-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "mskconnect_service_execution_role_policy" {
  role       = aws_iam_role.mskconnect_service_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKConnectorExecutionRole"
}

resource "aws_mskconnect_connector" "mskconnect_connector" {
  name                  = "debezium-connector"
  kafkaconnect_version  = "2.8.1"
  service_execution_role_arn = aws_iam_role.mskconnect_service_execution_role.arn

  connector_configuration = jsonencode({
    "connector.class" = "io.debezium.connector.kafka.KafkaConnector",
    "tasks.max" = "1",
    "topics" = "your_topic_name",
    "key.converter" = "org.apache.kafka.connect.storage.StringConverter",
    "value.converter" = "org.apache.kafka.connect.json.JsonConverter",
    "value.converter.schemas.enable" = "false"
  })

  kafka_cluster {
    apache_kafka_cluster {
      bootstrap_servers = aws_msk_cluster.msk_cluster.bootstrap_brokers_tls
      vpc {
        security_groups = aws_msk_cluster.msk_cluster.broker_node_group_info.security_groups
        subnets         = aws_msk_cluster.msk_cluster.broker_node_group_info.client_subnets
      }
    }
  }

  kafka_cluster_client_authentication {
    authentication_type = "NONE"
  }

  kafka_cluster_encryption_in_transit {
    encryption_type = "TLS"
  }

  plugin {
    custom_plugin {
      arn = aws_mskconnect_custom_plugin.mskconnect_custom_plugin.arn
      revision = aws_mskconnect_custom_plugin.mskconnect_custom_plugin.latest_revision
    }
  }

  capacity {
    auto_scaling {
      min_capacity = 1
      max_capacity = 1
    }
  }
}
```

This Terraform configuration sets up an Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes, creates an MSK Connect custom plugin using a "debezium.zip" file, and sets up an MSK Connect connector that uses the custom plugin to connect to the MSK cluster. The configuration includes necessary IAM roles and policies for the MSK Connect service execution role.

