### Description
The Terraform program below creates an Amazon RDS MySQL instance with 100 GB of allocated storage. The instance class is set to `db.t3.medium`, which is a common choice for moderate workloads. The configuration includes basic settings such as the engine version, username, and password. Additionally, it sets up a DB subnet group and security group to ensure the instance is properly networked.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_instance_identifier" {
  description = "Identifier for the RDS instance"
  default     = "my-mysql-instance"
}

variable "db_username" {
  description = "Username for the RDS instance"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the RDS instance"
  default     = "securepassword123"
}

resource "aws_db_subnet_group" "example" {
  name       = "my-mysql-subnet-group"
  subnet_ids = ["subnet-12345678", "subnet-87654321"]

  tags = {
    Name = "MyMySQLSubnetGroup"
  }
}

resource "aws_security_group" "example" {
  name        = "my-mysql-sg"
  description = "Allow MySQL traffic"
  vpc_id      = "vpc-12345678"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "MyMySQLSecurityGroup"
  }
}

resource "aws_db_instance" "mysql_cluster" {
  identifier              = var.db_instance_identifier
  instance_class          = "db.t3.medium"
  allocated_storage       = 100
  engine                  = "mysql"
  engine_version          = "8.0"
  username                = var.db_username
  password                = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.example.name
  vpc_security_group_ids  = [aws_security_group.example.id]
  skip_final_snapshot     = true
  publicly_accessible     = true

  tags = {
    Name = "MyMySQLCluster"
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Variables**: Default values are provided for the database instance identifier, username, and password.
- **DB Subnet Group**: A subnet group is created with two example subnet IDs. You should replace these with your actual subnet IDs.
- **Security Group**: A security group is set up to allow inbound traffic on port 3306 (MySQL default port) from any IP address. This is for demonstration purposes and should be restricted in a production environment.
- **DB Instance**: An RDS MySQL instance is created with the specified instance class, allocated storage, and other required attributes. The instance is associated with the previously created subnet group and security group.

This configuration ensures that the MySQL instance is properly set up with the required storage and network configurations. Adjust the subnet IDs, security group rules, and other parameters as needed for your specific environment.

