### Description
The Terraform program below creates a DynamoDB table with data encryption at rest enabled. It includes the necessary resources and configurations to ensure that the table is encrypted using an S3 bucket for storing the encryption key. The program also sets up the required IAM roles and permissions to allow DynamoDB to access the S3 bucket for encryption.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "dynamodb_encryption_role" {
  name = "dynamodb-encryption-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "dynamodb_encryption_policy" {
  name        = "dynamodb-encryption-policy"
  description = "Policy to allow DynamoDB to access S3 for encryption"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.my_dynamodb_table_encryption_bucket.id}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "dynamodb_encryption_policy_attachment" {
  role       = aws_iam_role.dynamodb_encryption_role.name
  policy_arn = aws_iam_policy.dynamodb_encryption_policy.arn
}

resource "aws_s3_bucket" "my_dynamodb_table_encryption_bucket" {
  bucket = "my-dynamodb-encryption-bucket-${random_string.suffix.result}"
  acl    = "private"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "my_dynamodb_table_encryption_config" {
  bucket = aws_s3_bucket.my_dynamodb_table_encryption_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_kms_key" "dynamodb_encryption_key" {
  description             = "KMS key for DynamoDB encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_dynamodb_table" "my_dynamodb_table" {
  name           = "my-dynamodb-table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
    kms_key_arn = aws_kms_key.dynamodb_encryption_key.arn
  }

  timeouts {
    create = "10m"
    update = "10m"
    delete = "10m"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

This Terraform configuration sets up a DynamoDB table with server-side encryption enabled using a KMS key. It also creates an S3 bucket for storing the encryption key and configures the necessary IAM roles and policies to allow DynamoDB to access the S3 bucket.

