  vpc_id = "vpc-12345678"  # Replace with your VPC ID

  ingress {
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = ["10.0.1.0/24", "10.0.2.0/24"]  # Replace with your subnet CIDRs
  }

