### Description
This Terraform program creates an AWS Redshift cluster with specific parameters and sets up notifications on events associated with the parameter group. The program includes the creation of a Redshift parameter group, a security group, and the Redshift cluster itself. The Redshift cluster depends on both the parameter group and the security group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_redshift_parameter_group" "example_parameter_group" {
  name   = "example-redshift-parameter-group"
  family = "redshift-1.x"

  parameter {
    name  = "auto_analyze"
    value = "on"
  }

  parameter {
    name  = "query_group"
    value = "example-query-group"
  }
}

resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = "vpc-12345678"  # Replace with your VPC ID

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust for your security needs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_redshift_cluster" "example_redshift_cluster" {
  cluster_identifier = "example-redshift-cluster"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  cluster_type       = "single-node"
  iam_roles          = ["arn:aws:iam::123456789012:role/RedshiftAccessRole"]

  cluster_parameter_group_name = aws_redshift_parameter_group.example_parameter_group.name
  vpc_security_group_ids       = [aws_security_group.redshift_sg.id]

  logging {
    enable       = true
    bucket_name  = "redshift-logs-bucket"
    s3_key_prefix = "logs/"
  }

  snapshot_copy {
    destination_region = "us-east-1"
    retention_period = 30
  }

  timeouts {
    create = "120m"
    update = "60m"
    delete = "60m"
  }
}
```

### Notes
- Ensure that the VPC ID (`vpc_id`) and the IAM role ARN (`iam_roles`) are replaced with valid values from your AWS account.
- The `master_password` should be a strong password that meets AWS security requirements.
- The `cidr_blocks` in the security group rules should be adjusted to match your network's security requirements.

