provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "codebuild_access_policy" {
  name        = "codebuild-access-policy"
  description = "Policy for AWS CodeBuild to access GitHub and S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::autograder-results-bucket",
          "arn:aws:s3:::autograder-results-bucket/*"
        ]
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_codebuild_policy" {
  policy_arn = aws_iam_policy.codebuild_access_policy.arn
  role       = aws_iam_role.codebuild_service_role.name
}

resource "aws_s3_bucket" "autograder_results_bucket" {
  bucket = "autograder-results-bucket"
}

resource "aws_s3_bucket_policy" "results_bucket_policy" {
  bucket = aws_s3_bucket.autograder_results_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:PutObject"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Resource = [
          "arn:aws:s3:::autograder-results-bucket/*"
        ]
      }
    ]
  })
}

resource "aws_codebuild_source_credential" "github_source_credential" {
  auth_type   = "PERSONAL_ACCESS_TOKEN"
  server_type = "GITHUB"
  token       = var.github_token
}

resource "aws_codebuild_project" "autograder_codebuild_project" {
