### Description
This Terraform program sets up an AWS infrastructure to run a code every day at 7 UTC using AWS EventBridge and AWS Lambda. The program includes the creation of an IAM role for the Lambda function, the Lambda function itself, an EventBridge rule to trigger the Lambda function daily, and the necessary permissions to allow EventBridge to invoke the Lambda function.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "lambda_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Effect = "Allow"
          Resource = "arn:aws:logs:*:*:*"
        }
      ]
    })
  }
}

resource "aws_lambda_function" "daily_task_lambda" {
  function_name = "daily_task_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function.zip"

  environment {
    variables = {
      LOG_LEVEL = "info"
    }
  }
}

resource "aws_cloudwatch_event_rule" "daily_schedule_rule" {
  name                = "daily_schedule_rule"
  schedule_expression = "cron(0 7 * * ? *)"
}

resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.daily_schedule_rule.name
  target_id = "lambda_target"
  arn       = aws_lambda_function.daily_task_lambda.arn
}

resource "aws_lambda_permission" "allow_eventbridge_invocation" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_task_lambda.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_schedule_rule.arn
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **IAM Role**: An IAM role named `lambda_execution_role` is created with a trust policy allowing Lambda to assume the role. An inline policy is added to allow the Lambda function to write logs to CloudWatch.
3. **Lambda Function**: A Lambda function named `daily_task_lambda` is created. It uses the IAM role created earlier, specifies a handler and runtime, and includes an environment variable.
4. **EventBridge Rule**: An EventBridge rule named `daily_schedule_rule` is created with a cron expression to trigger the Lambda function daily at 7 UTC.
5. **EventBridge Target**: An EventBridge target is created to link the EventBridge rule to the Lambda function.
6. **Lambda Permission**: A permission is granted to allow EventBridge to invoke the Lambda function.

