### Description
This Terraform program sets up a PostgreSQL 15 instance on AWS RDS within specific public subnets for running Airbyte connector test cases. The configuration includes the necessary resources and settings to ensure low maintenance and proper placement within the specified subnets and security groups.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Define the DB subnet group
resource "aws_db_subnet_group" "airbyte_postgresql_subnet_group" {
  name       = "airbyte-postgresql-subnet-group"
  subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]  # Replace with your public subnet IDs

  tags = {
    Name = "Airbyte PostgreSQL Subnet Group"
  }
}

# Define the DB security group
resource "aws_security_group" "airbyte_postgresql_sg" {
  name        = "airbyte-postgresql-sg"
  description = "Security group for Airbyte PostgreSQL instance"
  vpc_id      = "vpc-0123456789abcdef0"  # Replace with your VPC ID

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust as needed for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Airbyte PostgreSQL Security Group"
  }
}

# Define the RDS PostgreSQL instance
resource "aws_db_instance" "airbyte_postgresql_instance" {
  instance_class           = "db.t3.micro"
  engine                   = "postgres"
  engine_version           = "15"
  allocated_storage        = 20
  username                 = "airbyte"
  password                 = "securepassword"  # Replace with a secure password
  db_name                  = "airbyte_db"
  db_subnet_group_name     = aws_db_subnet_group.airbyte_postgresql_subnet_group.name
  vpc_security_group_ids   = [aws_security_group.airbyte_postgresql_sg.id]
  backup_retention_period  = 7
  skip_final_snapshot      = true

  timeouts {
    create = "30m"
    update = "30m"
    delete = "30m"
  }

  tags = {
    Name = "Airbyte PostgreSQL Instance"
  }
}
```

### Notes
- **Region**: Ensure the `region` in the provider configuration matches your desired AWS region.
- **Subnet IDs and VPC ID**: Replace the placeholder subnet IDs and VPC ID with your actual AWS resource IDs.
- **Security Group**: The security group allows inbound traffic on port 5432. Adjust the `cidr_blocks` as needed for your security requirements.
- **Password**: Replace `"securepassword"` with a strong, secure password for the database instance.
- **Backup Retention**: The `backup_retention_period` is set to 7 days. Adjust as needed based on your backup requirements.
- **Final Snapshot**: The `skip_final_snapshot` is set to `true` to avoid creating a final snapshot when the instance is deleted. Adjust this setting based on your retention policies.

