    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "my-db-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]
}

resource "aws_db_instance" "mysql_rds_instance" {
  instance_class       = "db.t3.micro"
  allocated_storage    = 10
  engine               = "mysql"
  engine_version       = "5.7"
  username             = "admin"
  password             = "password"
  db_subnet_group_name = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.db_security_group.id]
  publicly_accessible  = true
  storage_type         = "gp2"
}
```

This Terraform configuration sets up an AWS environment with a main VPC, two subnets across different availability zones, and a security group to allow database access. It also configures a 10 GB MySQL RDS instance with public accessibility, linked to the defined subnets and security group, and outputs the database endpoint for connectivity.

