### Description

This Terraform program sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the following components:

1. **VPC**: A Virtual Private Cloud (VPC) to host the Aurora cluster.
2. **Subnets**: Two subnets within the VPC.
3. **Security Group**: A security group to control inbound and outbound traffic to the Aurora cluster.
4. **IAM Role**: An IAM role with necessary permissions for the Aurora cluster.
5. **RDS Cluster**: An Aurora MySQL cluster configured with the specified subnets and security group.
6. **DB Proxy**: A database proxy to manage connections to the Aurora cluster.
7. **Secrets Manager Secret**: A secret in AWS Secrets Manager to store the database credentials securely.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "aurora_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "aurora_subnet_1" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "aurora_subnet_2" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "aurora_sg" {
  vpc_id = aws_vpc.aurora_vpc.id
  name   = "aurora-sg"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "aurora_iam_role" {
  name = "aurora-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "aurora_iam_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSDbProxyEndpoint"
  role       = aws_iam_role.aurora_iam_role.name
}

resource "aws_rds_cluster" "aurora_cluster" {
  engine              = "aurora-mysql"
  engine_version      = "8.0.mysql_aurora.3.02.0"
  cluster_identifier  = "aurora-cluster"
  master_username     = "admin"
  master_password     = "password123"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name = "aurora-subnet-group"
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]
  skip_final_snapshot = false
  final_snapshot_identifier = "snapshot"
}

resource "aws_db_proxy" "aurora_proxy" {
  name                   = "aurora-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.aurora_iam_role.arn
  vpc_subnet_ids         = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]

  auth {
    auth_scheme = "SECRETS"
    secret_arn  = aws_secretsmanager_secret.aurora_credentials.arn
    username    = "admin"
  }
}

resource "aws_db_proxy_default_target_group" "aurora_proxy_target_group" {
  db_proxy_name = aws_db_proxy.aurora_proxy.name
}

resource "aws_db_proxy_endpoint" "aurora_proxy_endpoint" {
  db_proxy_name         = aws_db_proxy.aurora_proxy.name
  db_proxy_endpoint_name = "aurora-proxy-endpoint"
  vpc_subnet_ids        = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]
}

resource "aws_secretsmanager_secret" "aurora_credentials" {
  name = "aurora-credentials"
}

resource "aws_secretsmanager_secret_version" "aurora_credentials_version" {
  secret_id     = aws_secretsmanager_secret.aurora_credentials.id
  secret_string = jsonencode({
    username = "admin"
    password = "password123"
  })
}
```

### Explanation

- **VPC and Subnets**: The VPC is created with a CIDR block of `10.0.0.0/16`. Two subnets are created within this VPC, each in a different availability zone.
- **Security Group**: A security group is created to allow inbound traffic on port 3306 (MySQL) from any IP address. Outbound traffic is allowed to any IP address.
- **IAM Role**: An IAM role is created with a trust policy allowing RDS to assume the role. The role is attached to the `AmazonRDSDbProxyEndpoint` policy.
- **RDS Cluster**: An Aurora MySQL cluster is created with the specified subnets and security group. The cluster is configured to take a final snapshot with the identifier "snapshot".
- **DB Proxy**: A database proxy is created to manage connections to the Aurora cluster. The proxy uses the IAM role and the secrets stored in AWS Secrets Manager.
- **Secrets Manager Secret**: A secret is created in AWS Secrets Manager to store the database credentials. The secret version contains the username and password for the database.

