### Description
The Terraform program below creates an Application Load Balancer (ALB) with an "authenticate-cognito" action. This involves setting up an ALB, a listener, and a rule to authenticate users via Cognito. The program also includes necessary IAM roles and policies to allow the ALB to interact with Cognito.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "authenticate_cognito_lb" {
  name               = "authenticate-cognito-lb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-0123456789abcdef0"  # Replace with your subnet ID
  }

  security_groups = ["sg-0123456789abcdef0"]  # Replace with your security group ID

  enable_deletion_protection = false
}

resource "aws_lb_listener" "authenticate_cognito_listener" {
  load_balancer_arn = aws_lb.authenticate_cognito_lb.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS-1-2-Ext-2018-06"
  certificate_arn   = "arn:aws:acm:us-west-2:123456789012:certificate/your-certificate-arn"  # Replace with your ACM certificate ARN

  default_action {
    type             = "authenticate-cognito"
    authenticate_cognito {
      user_pool_arn       = "arn:aws:cognito-idp:us-west-2:123456789012:userpool/us-west-2_abcdef123"  # Replace with your Cognito User Pool ARN
      user_pool_client_id = "your-user-pool-client-id"  # Replace with your Cognito User Pool Client ID
      user_pool_domain    = "your-cognito-domain.auth.us-west-2.amazoncognito.com"  # Replace with your Cognito Domain
    }
  }
}

resource "aws_iam_role" "lb_cognito_auth_role" {
  name = "lb-cognito-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lb_cognito_auth_policy" {
  role       = aws_iam_role.lb_cognito_auth_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}
```

### Notes
- Replace placeholders like `subnet-0123456789abcdef0`, `sg-0123456789abcdef0`, `arn:aws:acm:us-west-2:123456789012:certificate/your-certificate-arn`, `arn:aws:cognito-idp:us-west-2:123456789012:userpool/us-west-2_abcdef123`, `your-user-pool-client-id`, and `your-cognito-domain.auth.us-west-2.amazoncognito.com` with your actual AWS resource identifiers.
- The IAM role and policy attachment are included to ensure the ALB has the necessary permissions to interact with Cognito. Adjust the policy as needed based on your specific requirements.

