```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "example_lb" {
  name               = "example-lb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-12345678"
  }

  security_groups = ["sg-12345678"]
}

resource "aws_lb_listener" "example_listener" {
  load_balancer_arn = aws_lb.example_lb.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS-1-2-Ext-2018-06"
  certificate_arn   = "arn:aws:acm:us-west-2:123456789012:certificate/12345678-1234-1234-1234-123456789012"

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Hello, World!"
      status_code  = "200"
    }
  }
}

resource "aws_cognito_user_pool" "example_user_pool" {
  name = "example-user-pool"
}

resource "aws_cognito_user_pool_client" "example_user_pool_client" {
  name         = "example-user-pool-client"
  user_pool_id = aws_cognito_user_pool.example_user_pool.id
  generate_secret = true
}

resource "aws_lb_listener_rule" "example_listener_rule" {
  listener_arn = aws_lb_listener.example_listener.arn
  priority     = 1

  action {
    type = "authenticate-oidc"

    authenticate_oidc {
      authorization_endpoint = "https://cognito-idp.us-west-2.amazonaws.com/${aws_cognito_user_pool.example_user_pool.id}/oauth2/authorize"
      client_id              = aws_cognito_user_pool_client.example_user_pool_client.id
      client_secret          = aws_cognito_user_pool_client.example_user_pool_client.client_secret
      issuer                 = "https://cognito-idp.us-west-2.amazonaws.com/${aws_cognito_user_pool.example_user_pool.id}"
      token_endpoint         = "https://cognito-idp.us-west-2.amazonaws.com/${aws_cognito_user_pool.example_user_pool.id}/oauth2/token"
      user_info_endpoint     = "https://cognito-idp.us-west-2.amazonaws.com/${aws_cognito_user_pool.example_user_pool.id}/oauth2/userinfo"
      session_cookie_name    = "AWSELBAuthSessionCookie"
      scope                  = "openid"
      on_unauthenticated_request = "authenticate"
    }
  }

  condition {
    field  = "host-header"
    values = ["example.com"]
  }
}
```

This Terraform configuration sets up an Application Load Balancer with an HTTPS listener and an Authenticate-OIDC action using Amazon Cognito for authentication. The Cognito User Pool and User Pool Client are created, and the Authenticate-OIDC action is configured in the listener rule.

