LLM Output #0:
### Description
This Terraform program sets up an AWS infrastructure consisting of an Application Load Balancer (ALB), a Lambda function, and a Lambda Target Group. The ALB distributes incoming traffic to the Lambda function via the Target Group. An IAM role is created for the Lambda function to execute.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  ]
}

resource "aws_lambda_function" "example_lambda_function" {
  function_name = "example_lambda_function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function.zip"
}

resource "aws_lb" "example_load_balancer" {
  name               = "example-load-balancer"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-0123456789abcdef0"  # Replace with your subnet ID
  }

  security_groups = ["sg-0123456789abcdef0"]  # Replace with your security group ID

  enable_deletion_protection = false
}

resource "aws_lb_target_group" "example_lb_target_group" {
  name     = "example-lb-target-group"
  port     = 443
  protocol = "HTTPS"
  vpc_id   = "vpc-0123456789abcdef0"  # Replace with your VPC ID

  lambda_multi_value_headers_enabled = true

  health_check {
    enabled             = true
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
    path                = "/health"
  }

  stickiness {
    type            = "lb_cookie"
    cookie_duration = 86400
  }
}
```

### Notes
- Ensure that the subnet IDs, security group IDs, and VPC IDs are replaced with actual values from your AWS account.
- The Lambda function's `filename` should point to a valid ZIP file containing your Lambda code.
- The IAM role attached to the Lambda function includes the `AWSLambdaBasicExecutionRole` managed policy, which provides basic logging permissions. Adjust the policies as needed based on your requirements.

